import{_ as t,c as a,o as r,aj as s}from"./chunks/framework.B-K7myP5.js";const p=JSON.parse('{"title":"Shields.io","description":"提供简洁、一致且易读的SVG和点阵格式徽章服务，可以轻松地包含在GitHub的说明文件或其他网页中。","frontmatter":{"title":"Shields.io","description":"提供简洁、一致且易读的SVG和点阵格式徽章服务，可以轻松地包含在GitHub的说明文件或其他网页中。","lastUpdated":"2026-02-27","tags":[],"link":"/awesome/other/shields","tag":"图标","layout":"doc","sidebar":true,"aside":true},"headers":[],"params":{"pkg":"other/shields","sidebar":[{"text":"图标","items":[{"text":"Shields.io","link":"/awesome/other/shields","description":"提供简洁、一致且易读的SVG和点阵格式徽章服务，可以轻松地包含在GitHub的说明文件或其他网页中。"}]}]},"relativePath":"awesome/other/shields.md","filePath":"awesome/[pkg].md"}'),o={name:"awesome/other/shields.md"};function i(n,e,l,d,h,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<p>This is home to <a href="https://shields.io/" target="_blank" rel="noreferrer">Shields.io</a>, a service for concise, consistent, and legible badges in SVG and raster format, which can easily be included in GitHub readmes or any other web page. The service supports dozens of continuous integration services, package registries, distributions, app stores, social networks, code coverage services, and code analysis services. Every month it serves over 1.6 billion images and is used by some of the world&#39;s most popular open-source projects, [VS Code][vscode], [Vue.js][vue] and [Bootstrap][bootstrap] to name a few.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><ul><li>code coverage percentage: <img src="https://img.shields.io/badge/coverage-80%25-yellowgreen" alt="coverage" loading="lazy"></li><li>stable release version: <img src="https://img.shields.io/badge/version-1.2.3-blue" alt="version" loading="lazy"></li><li>package manager release: <img src="https://img.shields.io/badge/gem-2.2.0-blue" alt="gem" loading="lazy"></li><li>status of third-party dependencies: <img src="https://img.shields.io/badge/dependencies-out%20of%20date-orange" alt="dependencies" loading="lazy"></li><li>static code analysis grade: <img src="https://img.shields.io/badge/codacy-B-green" alt="codacy" loading="lazy"></li><li><a href="https://semver.org/" target="_blank" rel="noreferrer">SemVer</a> version observance: <img src="https://img.shields.io/badge/semver-2.0.0-blue" alt="semver" loading="lazy"></li><li>amount of <a href="https://liberapay.com/" target="_blank" rel="noreferrer">Liberapay</a> donations per week: <img src="https://img.shields.io/badge/receives-2.00%20USD%2Fweek-yellow" alt="receives" loading="lazy"></li><li>Python package downloads: <img src="https://img.shields.io/badge/downloads-13k%2Fmonth-brightgreen" alt="downloads" loading="lazy"></li><li>Chrome Web Store extension rating: <img src="https://img.shields.io/badge/rating-%E2%98%85%E2%98%85%E2%98%85%E2%98%85%E2%98%86-brightgreen" alt="rating" loading="lazy"></li><li>Uptime Robot uptime percentage: <img src="https://img.shields.io/badge/uptime-100%25-brightgreen" alt="uptime" loading="lazy"></li></ul><p><a href="https://img.shields.io/badges/static-badge" target="_blank" rel="noreferrer">Make your own badges!</a> (Quick example: <code>https://img.shields.io/badge/left-right-f39f37</code>)</p><h3 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to “Quickstart”">​</a></h3><p>Browse a <a href="https://shields.io/" target="_blank" rel="noreferrer">complete list of badges</a> and locate a particular badge by using the search bar or by browsing the categories. Click on the badge to fill in required data elements for that badge type (like your username or repo) and optionally customize (label, colors etc.). And it&#39;s ready for use!</p><p>Use the button at the bottom to copy your badge url or snippet, which can then be added to places like your GitHub readme files or other web pages.</p><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to “Contributing”">​</a></h2><p>Shields is a community project. We invite your participation through issues and pull requests! You can peruse the <a href="https://github.com/badges/shields/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer">contributing guidelines</a>.</p><p>When adding or changing a service <a href="https://github.com/badges/shields/blob/master/doc/service-tests.md" target="_blank" rel="noreferrer">please add tests</a>.</p><p>This project has quite a backlog of suggestions! If you&#39;re new to the project, maybe you&#39;d like to open a pull request to address one of them.</p><p>You can read a <a href="https://github.com/badges/shields/blob/master/doc/TUTORIAL.md" target="_blank" rel="noreferrer">tutorial on how to add a badge</a>.</p><p><a href="https://github.com/badges/shields/issues?q=is%3Aissue+is%3Aopen+label%3A%22good+first+issue%22" target="_blank" rel="noreferrer"><img src="https://img.shields.io/github/issues/badges/shields/good%20first%20issue" alt="GitHub issues by-label" loading="lazy"></a></p><p>If you intend on reporting or contributing a fix related to security vulnerabilities, please first refer to our <a href="https://github.com/badges/shields/blob/master/SECURITY.md" target="_blank" rel="noreferrer">security policy</a>.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to “Development”">​</a></h2><p><a href="https://codespaces.new/badges/shields?quickstart=1" target="_blank" rel="noreferrer"><img src="https://github.com/codespaces/badge.svg" alt="Open in GitHub Codespaces" loading="lazy"></a></p><ol><li>Install Node 22. You can use the <a href="https://nodejs.org/en/download/package-manager/" target="_blank" rel="noreferrer">package manager</a> of your choice.</li><li>Clone this repository.</li><li>Run <code>npm ci</code> to install the dependencies.</li><li>Run <code>npm start</code> to start the badge server and the frontend dev server.</li><li>Open <code>http://localhost:3000/</code> to view the frontend.</li></ol><p>When server source files change, the badge server should automatically restart itself (using <a href="https://nodemon.io/" target="_blank" rel="noreferrer">nodemon</a>). When the frontend files change, the frontend dev server (<code>docusaurus start</code>) should also automatically reload. However the badge definitions are built only before the server first starts. To regenerate those, either run <code>npm run prestart</code> or manually restart the server.</p><p>To debug a badge from the command line, run <code>npm run badge -- /npm/v/nock</code>. It also works with full URLs like <code>npm run badge -- https://img.shields.io/npm/v/nock</code>.</p><p>Use <code>npm run debug:server</code> to start server in debug mode. <a href="https://github.com/Microsoft/vscode-recipes/tree/master/nodemon" target="_blank" rel="noreferrer">This recipe</a> shows how to debug Node.js application in <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VS Code</a>.</p><p><a href="https://glebbahmutov.com/blog/snapshot-testing/" target="_blank" rel="noreferrer">Snapshot tests</a> ensure we don&#39;t inadvertently make changes that affect the SVG or JSON output. When deliberately changing the output, run <code>SNAPSHOT_DRY=1 npm run test:package</code> to preview changes to the saved snapshots, and <code>SNAPSHOT_UPDATE=1 npm run test:package</code> to update them.</p><p>The server can be configured to use <a href="https://sentry.io/" target="_blank" rel="noreferrer">Sentry</a> (<a href="https://github.com/badges/shields/blob/master/doc/self-hosting.md#sentry" target="_blank" rel="noreferrer">configuration</a>) and <a href="https://prometheus.io/" target="_blank" rel="noreferrer">Prometheus</a> (<a href="https://github.com/badges/shields/blob/master/doc/self-hosting.md#prometheus" target="_blank" rel="noreferrer">configuration</a>).</p><p>Our <a href="https://github.com/badges/shields/actions/workflows/daily-tests.yml" target="_blank" rel="noreferrer">full test suite</a> as well as <a href="https://coveralls.io/github/badges/shields" target="_blank" rel="noreferrer">code coverage</a> are run on a daily basis.</p><h2 id="hosting-your-own-server" tabindex="-1">Hosting your own server <a class="header-anchor" href="#hosting-your-own-server" aria-label="Permalink to “Hosting your own server”">​</a></h2><p>There is documentation about <a href="https://github.com/badges/shields/blob/master/doc/self-hosting.md" target="_blank" rel="noreferrer">hosting your own server</a>.</p><h2 id="related-projects" tabindex="-1">Related projects <a class="header-anchor" href="#related-projects" aria-label="Permalink to “Related projects”">​</a></h2><p><a href="https://awesome.re" target="_blank" rel="noreferrer"><img src="https://awesome.re/badge.svg" alt="Awesome" loading="lazy"></a></p><p>Status badges are used widely across open-source and private software projects. Academics have studied the &quot;signal&quot; badges provide about software project quality. There are many existing libraries for rendering these badges, and alternatives to the hosted Shields badge service. <a href="https://github.com/badges/awesome-badges" target="_blank" rel="noreferrer">awesome-badges</a> is a curated collection of such resources. <a href="https://github.com/badges/awesome-badges/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">Contributions</a> may be considered there. (The presence of a project in that collection should not be interpreted as an endorsement nor promotion from the Shields project)</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to “History”">​</a></h2><p>b.adge.me was the original website for this service. Heroku back then had a thing which made it hard to use a toplevel domain with it, hence the odd domain. It used code developed in 2013 from a library called <a href="https://github.com/badges/gh-badges" target="_blank" rel="noreferrer">gh-badges</a>, both developed by <a href="https://github.com/espadrine" target="_blank" rel="noreferrer">Thaddée Tyl</a>. The project merged with shields.io by making it use the b.adge.me code and closed b.adge.me.</p><p>The original badge specification was developed in 2013 by <a href="https://github.com/olivierlacan" target="_blank" rel="noreferrer">Olivier Lacan</a>. It was inspired by the Travis CI and similar badges (there were a lot fewer, back then). In 2014 Thaddée Tyl redesigned it with help from a Travis CI employee and convinced everyone to switch to it. The old design is what today is called the plastic style; the new one is the flat style.</p><p>You can read more about <a href="https://github.com/h5bp/lazyweb-requests/issues/150" target="_blank" rel="noreferrer">the project&#39;s inception</a>, <a href="https://github.com/badges/shields/blob/master/spec/motivation.md" target="_blank" rel="noreferrer">the motivation of the SVG badge specification</a>, and <a href="https://github.com/badges/shields/blob/master/spec/SPECIFICATION.md" target="_blank" rel="noreferrer">the specification itself</a>.</p>',32)])])}const b=t(o,[["render",i]]);export{p as __pageData,b as default};
